"""Compact calendar view for due dates."""
import calendar
import datetime as dt
import re


def _add_months(day, amount):
    idx=day.year*12+day.month-1+amount
    y,m=divmod(idx,12);m+=1
    return dt.date(y,m,min(day.day,calendar.monthrange(y,m)[1]))

def _delta(token):
    if not token:return 0,'d'
    m=re.fullmatch(r'([+-]?\d*)([dwmy]?)',token)
    if not m:return None
    return (int(m[1] or ('-1' if token.startswith('-') else '1')),m[2] or 'd')

def _shift(day,n,unit):
    if unit=='d':return day+dt.timedelta(days=n)
    if unit=='w':return day+dt.timedelta(days=n*7)
    if unit=='m':return _add_months(day,n)
    return _add_months(day,n*12)

def _range(spec,today):
    strict=(spec or '').startswith('+')
    s=(spec or '1m')
    if strict:s=s[1:]
    if '..' in s:
        a,b=s.split('..',1);da=_delta(a);db=_delta(b)
        if da is None or db is None:return None
        start=_shift(today,*da) if a else today
        end=_shift(today,*db) if b else today
        return (min(start,end),max(start,end))
    d=_delta(s)
    if d is None:return None
    n,u=d
    if u in ('w','m','y') and not strict:
        if u=='w':
            base=today-dt.timedelta(days=(today.weekday()+1)%7)
            count=max(1,abs(n))
            start=base-dt.timedelta(days=7*(count-1)) if n<0 else base
            return start,start+dt.timedelta(days=7*count-1)
        months=max(1,abs(n))
        if n<0:
            first=dt.date(today.year,today.month,1)
            start=_add_months(first,-(months-1));end=dt.date(today.year,today.month,calendar.monthrange(today.year,today.month)[1])
        else:
            start=dt.date(today.year,today.month,1)
            end0=_add_months(start,months)
            end=end0-dt.timedelta(days=1)
        return start,end
    if strict:
        count=abs(n or 1)*(7 if u=='w' else 30 if u=='m' else 365 if u=='y' else 1)
        if n<0:return today-dt.timedelta(days=count-1),today
        return today,today+dt.timedelta(days=count-1)
    if n<0:return _shift(today,n,u),today
    return today,_shift(today,n,u)

def render_calendar(lines,spec='1m',today=None,colors=True):
    today=today or dt.date.today()
    bounds=_range(spec,today)
    if not bounds:return ''
    start,end=bounds
    due_counts={}
    for line in lines:
        if re.match(r'^x(?:\s|$)',line) or re.search(r'(?<!\S)h:[^\s]+',line):continue
        m=re.search(r'(?<!\S)due:(\d{4}-\d\d-\d\d)(?!\S)',line)
        if m:
            try:d=dt.date.fromisoformat(m[1])
            except ValueError:continue
            if start<=d<=end:due_counts[d]=due_counts.get(d,0)+1
    months=[]
    cursor=dt.date(start.year,start.month,1)
    while cursor<=end:
        months.append(cursor)
        cursor=_add_months(cursor,1)
    blocks=[]
    for month in months:
        first=month-dt.timedelta(days=(month.weekday()+1)%7)
        lastday=dt.date(month.year,month.month,calendar.monthrange(month.year,month.month)[1])
        last=lastday+dt.timedelta(days=(5-lastday.weekday())%7)
        rows=[];weekstart=first
        while weekstart<=last:
            cells=[];active=False
            for i in range(7):
                day=weekstart+dt.timedelta(days=i)
                visible=day.month==month.month and start<=day<=end
                active=active or visible
                if not visible:cells.append('   ');continue
                count=due_counts.get(day,0)
                if colors:
                    fg='\x1b[31m' if count>1 else '\x1b[35m' if count==1 else '\x1b[0m'
                    bg='\x1b[44m' if day==today else ''
                    cells.append(f'{fg}{bg}{day.day:2d}\x1b[0m')
                else:cells.append(f'{day.day:2d}')
            if active:
                week=(weekstart+dt.timedelta(days=1)).isocalendar().week
                label=f'\x1b[0m\x1b[32m {week:02d}\x1b[0m' if colors else f' {week:02d}'
                rows.append(label+''.join(cells))
            weekstart+=dt.timedelta(days=7)
        blocks.append((month.strftime('%B').center(24),rows))
    spacer='    '
    headings=['    Su Mo Tu We Th Fr Sa']+['Su Mo Tu We Th Fr Sa']*(len(blocks)-1)
    out=[spacer.join(b[0] for b in blocks),spacer.join(headings)]
    rowcount=max((len(b[1]) for b in blocks),default=0)
    for i in range(rowcount):
        out.append(' '.join(b[1][i] if i<len(b[1]) else ' '*25 for b in blocks))
    return '\n'.join(out)+'\n\n'

